import { relations } from "drizzle-orm";
import {
  boolean,
  integer,
  pgTable,
  text,
  timestamp,
  varchar,
} from "drizzle-orm/pg-core";
import { companyName } from "./company-name";

/*
CREATE TABLE "company_alias" (
    "pk"           integer                  GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name"         varchar(128)             NOT NULL UNIQUE,
    "logo_key"     text                     NULL,
    "needs_review" boolean                  NOT NULL DEFAULT false,
    "created_at"   timestamp with time zone NOT NULL DEFAULT NOW(),
    "updated_at"   timestamp with time zone NOT NULL DEFAULT NOW()
);
*/
// 회사 (공식 이름). 현업자 목록 등 화면에는 이 이름과 로고가 나감
// 사람마다 다른 표기(microsoft, 마이크로소프트, 마소 ...)는 company_name 에 묶임
export const companyAlias = pgTable("company_alias", {
  // 삭제한 pk를 다시 쓰지 않도록 시퀀스로 발급
  pk: integer("pk").primaryKey().generatedByDefaultAsIdentity().notNull(),
  name: varchar("name", { length: 128 }).notNull().unique(),
  // S3 key (company-logo/...). 없으면 null
  logoKey: text("logo_key"),
  // 현업자가 등록되지 않은 이름을 입력해 생긴 회사. 어드민이 승인하거나 다른 회사에 병합
  needsReview: boolean("needs_review").notNull().default(false),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

export const companyAliasRelations = relations(companyAlias, ({ many }) => ({
  names: many(companyName),
}));
